package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_hasAttr_TriageGen1Test {

    private Node node;
    private Attributes attributes;

    @Before
    public void setUp() {
        attributes = new Attributes();
        node = new Node() {
            @Override
            public String nodeName() {
                return "#document";
            }
        };
    }

    @Test
    public void testHasAttr_WithExistingAttribute_ShouldReturnTrue() {
        attributes.put("href", "http://example.com");
        node = new Node(null, attributes) {};
        assertTrue(node.hasAttr("href"));
    }

    @Test
    public void testHasAttr_WithNonExistingAttribute_ShouldReturnFalse() {
        node = new Node(null, attributes) {};
        assertFalse(node.hasAttr("href"));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testHasAttr_WithNullAttributeKey_ShouldThrowException() {
        node.hasAttr(null);
    }

    @Test
    public void testHasAttr_WithEmptyAttributeKey_ShouldReturnFalse() {
        assertFalse(node.hasAttr(""));
    }

    @Test
    public void testHasAttr_WithWhitespaceAttributeKey_ShouldReturnFalse() {
        assertFalse(node.hasAttr("   "));
    }
}
